tests:
test({ sr: 'vraća poslednje elemente', en: 'returns the last items' }, () => {
  expect(lastItems([1, 2, 3, 4], 2)).toEqual([3, 4]);
});
test({ sr: 'veći broj od dužine daje ceo niz', en: 'a count larger than the length gives the whole array' }, () => {
  expect(lastItems([1, 2], 5)).toEqual([1, 2]);
});
test({ sr: 'nula daje prazan niz', en: 'zero gives an empty array' }, () => {
  expect(lastItems([1, 2, 3], 0)).toEqual([]);
});

hiddenTests:
test('an empty array gives an empty array', () => {
  expect(lastItems([], 3)).toEqual([]);
});
test('one item', () => {
  expect(lastItems(['a', 'b', 'c'], 1)).toEqual(['c']);
});
test('the original array is not changed', () => {
  const input = [1, 2, 3];
  lastItems(input, 2);
  expect(input).toEqual([1, 2, 3]);
});
test('the result is a new array', () => {
  const input = [1, 2, 3];
  expect(lastItems(input, 3)).not.toBe(input);
});

solutions.code:
function lastItems(items, count) {
  const start = items.length - count;
  return items.slice(start < 0 ? 0 : start);
}
